using Myriale.Api.Architecture;
namespace Myriale.Api.Features.Dashboard;
[FeatureSlice("Dashboard")] public static class DashboardFeature { public static IServiceCollection AddDashboardFeature(this IServiceCollection s){s.AddScoped<IHomeDashboardService,DemoHomeDashboardService>();return s;} public static IEndpointRouteBuilder MapDashboardFeature(this IEndpointRouteBuilder e){e.MapGet("/api/home/dashboard",async(System.Security.Claims.ClaimsPrincipal p,IHomeDashboardService d,CancellationToken ct)=>{var id=p.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;return string.IsNullOrWhiteSpace(id)?Results.Unauthorized():Results.Ok(await d.GetDashboardAsync(id,ct));}).WithName("GetHomeDashboard").WithSummary("Returns the data required to render the current user's home dashboard.").RequireAuthorization().RequireCors("MyrialeFrontend");return e;} }
